Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='budgetcountsshown', at=datetime(2026, 11, 25, 0, 0, 0), actor='assistant', title='A step or budget measured over a log counts what the reader is shown of each line, not what the log stores', body='A step or a budget that is measured over a log counts the bytes of each line as the reader is shown it: after the view has cut it, hidden its words or joined its spaces. It does not count the bytes the log stores. A line that is long in storage and short in the view otherwise moves the step or the budget, although the reader sees no change.', rationale="A hidden long line has a stored length that the reader never sees. A step that counts the stored length moves when that line arrives, so the record's frozen part and its handles change with no visible cause, and a budget is spent on bytes that nobody reads.", supersedes=()))